 18→// RunAccessible runs a text-based menu for accessibility mode.
 19→func RunAccessible(w io.Writer, _ io.Writer) error {
 20→	for {
 21→		var choice string
 22→
 23→		form := huh.NewForm(
 24→			huh.NewGroup(
 25→				huh.NewSelect[string]().
 26→					Title("Entire Dashboard").
 27→					Options(
 28→						huh.NewOption("View sessions", "sessions"),
 29→						huh.NewOption("View checkpoints", "checkpoints"),
 30→						huh.NewOption("View active sessions", "active"),
 31→						huh.NewOption("View settings", "settings"),
 32→						huh.NewOption("Quit", "quit"),
 33→					).
 34→					Value(&choice),
 35→			),
 36→		).WithAccessible(true)
 37→
 38→		if err := form.Run(); err != nil {
 39→			return fmt.Errorf("menu selection failed: %w", err)
 40→		}
 41→
 42→		switch choice {
 43→		case "sessions":
 44→			if err := showAccessibleSessions(w); err != nil {
 45→				fmt.Fprintf(w, "Error: %v\n", err)
 46→			}
 47→		case "checkpoints":
 48→			if err := showAccessibleCheckpoints(w); err != nil {
 49→				fmt.Fprintf(w, "Error: %v\n", err)
 50→			}
 51→		case "active":
 52→			if err := showAccessibleActive(w); err != nil {
 53→				fmt.Fprintf(w, "Error: %v\n", err)
 54→			}
 55→		case "settings":
 56→			if err := showAccessibleSettings(w); err != nil {
 57→				fmt.Fprintf(w, "Error: %v\n", err)
 58→			}
 59→		case "quit":
 60→			return nil
 61→		}
 62→
 63→		fmt.Fprintln(w)
 64→	}
 65→}
