 67→func showAccessibleSessions(w io.Writer) error {
 68→	sessions, err := strategy.ListSessions()
 69→	if err != nil {
 70→		return fmt.Errorf("loading sessions: %w", err)
 71→	}
 72→
 73→	if len(sessions) == 0 {
 74→		fmt.Fprintln(w, "\nNo sessions found.")
 75→		return nil
 76→	}
 77→
 78→	fmt.Fprintf(w, "\nSessions (%d):\n", len(sessions))
 79→	fmt.Fprintln(w, strings.Repeat("-", 60))
 80→
 81→	for _, s := range sessions {
 82→		shortID := s.ID
 83→		if len(shortID) > 12 {
 84→			shortID = shortID[:12]
 85→		}
 86→		desc := s.Description
 87→		if desc == "" || desc == strategy.NoDescription {
 88→			desc = "(no description)"
 89→		} else {
 90→			desc = truncate(desc, 50)
 91→		}
 92→		fmt.Fprintf(w, "  %-12s  %s  %s  %d checkpoints\n",
 93→			shortID, desc, timeAgo(s.StartTime), len(s.Checkpoints))
 94→	}
 95→
 96→	return nil
 97→}
