 99→func showAccessibleCheckpoints(w io.Writer) error {
100→	strat := getConfiguredStrategy()
101→	if strat == nil {
102→		return errors.New("no strategy configured")
103→	}
104→
105→	points, err := strat.GetRewindPoints(50)
106→	if err != nil {
107→		return fmt.Errorf("loading checkpoints: %w", err)
108→	}
109→
110→	if len(points) == 0 {
111→		fmt.Fprintln(w, "\nNo checkpoints found.")
112→		return nil
113→	}
114→
115→	fmt.Fprintf(w, "\nCheckpoints (%d):\n", len(points))
116→	fmt.Fprintln(w, strings.Repeat("-", 60))
117→
118→	for _, p := range points {
119→		cpType := cpTypeSession
120→		if p.IsTaskCheckpoint {
121→			cpType = cpTypeTask
122→		}
123→		if p.IsLogsOnly {
124→			cpType = cpTypeCommitted
125→		}
126→
127→		cpID := p.CheckpointID.String()
128→		if cpID == "" {
129→			cpID = truncate(p.ID, 12)
130→		}
131→
132→		prompt := truncate(p.SessionPrompt, 40)
133→		if prompt == "" {
134→			prompt = truncate(p.Message, 40)
135→		}
136→
137→		fmt.Fprintf(w, "  %-12s  [%-9s]  %-10s  %s\n",
138→			cpID, cpType, timeAgo(p.Date), prompt)
139→	}
140→
141→	return nil
142→}
