144→func showAccessibleActive(w io.Writer) error {
145→	store, err := session.NewStateStore()
146→	if err != nil {
147→		return fmt.Errorf("creating state store: %w", err)
148→	}
149→
150→	states, err := store.List(context.Background())
151→	if err != nil {
152→		return fmt.Errorf("listing sessions: %w", err)
153→	}
154→
155→	// Filter active
156→	var active []*session.State
157→	for _, s := range states {
158→		if s.EndedAt == nil {
159→			active = append(active, s)
160→		}
161→	}
162→
163→	if len(active) == 0 {
164→		fmt.Fprintln(w, "\nNo active sessions.")
165→		return nil
166→	}
167→
168→	fmt.Fprintf(w, "\nActive Sessions (%d):\n", len(active))
169→	fmt.Fprintln(w, strings.Repeat("-", 60))
170→
171→	for _, s := range active {
172→		shortID := s.SessionID
173→		if len(shortID) > 7 {
174→			shortID = shortID[:7]
175→		}
176→
177→		agentLabel := string(s.AgentType)
178→		if agentLabel == "" {
179→			agentLabel = "(unknown)"
180→		}
181→
182→		phase := string(s.Phase)
183→		if phase == "" {
184→			phase = "idle"
185→		}
186→
187→		prompt := truncate(s.FirstPrompt, 40)
188→
189→		fmt.Fprintf(w, "  %-9s  %-8s  %-14s  %s  %s\n",
