196→func showAccessibleSettings(w io.Writer) error {
197→	s, err := settings.Load()
198→	if err != nil {
199→		return fmt.Errorf("loading settings: %w", err)
200→	}
201→
202→	fmt.Fprintln(w, "\nSettings:")
203→	fmt.Fprintln(w, strings.Repeat("-", 40))
204→
205→	enabledStr := "Enabled"
206→	if !s.Enabled {
207→		enabledStr = "Disabled"
208→	}
209→	fmt.Fprintf(w, "  Status:    %s\n", enabledStr)
210→	fmt.Fprintf(w, "  Strategy:  %s\n", s.Strategy)
211→
212→	logLevel := s.LogLevel
213→	if logLevel == "" {
214→		logLevel = "info (default)"
215→	}
216→	fmt.Fprintf(w, "  Log Level: %s\n", logLevel)
217→
218→	telemetryStr := "not configured"
219→	if s.Telemetry != nil {
220→		if *s.Telemetry {
221→			telemetryStr = "opted in"
222→		} else {
223→			telemetryStr = "opted out"
224→		}
225→	}
226→	fmt.Fprintf(w, "  Telemetry: %s\n", telemetryStr)
227→
228→	fmt.Fprintln(w, "\nInstalled Agents:")
229→	agents := agent.List()
230→	if len(agents) == 0 {
231→		fmt.Fprintln(w, "  (none)")
232→	}
233→	for _, name := range agents {
234→		ag, agErr := agent.Get(name)
235→		if agErr != nil {
236→			continue
237→		}
238→		hooksStr := "no hooks"
239→		if hs, ok := ag.(agent.HookSupport); ok {
240→			if hs.AreHooksInstalled() {
241→				hooksStr = "hooks installed"
242→			} else {
243→				hooksStr = "hooks not installed"
244→			}
245→		}
246→		fmt.Fprintf(w, "  %s (%s) - %s\n", ag.Type(), name, hooksStr)
247→	}
248→
249→	return nil
250→}
