  1→package dashboard
  2→
  3→import (
  4→	"fmt"
  5→	"strings"
  6→
  7→	tea "github.com/charmbracelet/bubbletea"
  8→
  9→	"github.com/entireio/cli/cmd/entire/cli/strategy"
 10→)
 11→
 12→//nolint:recvcheck // bubbletea pattern: pointer receivers for mutating setters, value receivers for update/view
 13→type sessionsModel struct {
 14→	sessions   []strategy.Session
 15→	filtered   []strategy.Session
 16→	err        error
 17→	cursor     int
 18→	scrollPos  int
 19→	width      int
 20→	height     int
 21→	showDetail bool
 22→	filtering  bool
 23→	filter     string
 24→}
 25→
 26→func newSessionsModel() sessionsModel {
 27→	return sessionsModel{}
 28→}
 29→
 30→func (m *sessionsModel) setSize(width, height int) {
 31→	m.width = width
 32→	m.height = height
 33→}
 34→
 35→func (m *sessionsModel) setSessions(sessions []strategy.Session) {
 36→	m.sessions = sessions
 37→	m.applyFilter()
 38→}
 39→
 40→func (m *sessionsModel) applyFilter() {
 41→	if m.filter == "" {
 42→		m.filtered = m.sessions
 43→		return
 44→	}
 45→	lower := strings.ToLower(m.filter)
 46→	var filtered []strategy.Session
 47→	for _, s := range m.sessions {
 48→		if strings.Contains(strings.ToLower(s.ID), lower) ||
 49→			strings.Contains(strings.ToLower(s.Description), lower) ||
 50→			strings.Contains(strings.ToLower(s.Strategy), lower) {
 51→			filtered = append(filtered, s)
 52→		}
 53→	}
 54→	m.filtered = filtered
 55→	if m.cursor >= len(m.filtered) {
 56→		m.cursor = max(0, len(m.filtered)-1)
 57→	}
 58→}
 59→
 60→func (m sessionsModel) update(msg tea.Msg) (sessionsModel, tea.Cmd) { //nolint:unparam // tea.Cmd needed for consistent tab interface
 61→	keyMsg, ok := msg.(tea.KeyMsg)
 62→	if !ok {
 63→		return m, nil
 64→	}
 65→
 66→	if m.filtering {
 67→		switch keyMsg.String() {
 68→		case keyEsc:
 69→			m.filtering = false
 70→			m.filter = ""
 71→			m.applyFilter()
 72→		case keyEnter:
 73→			m.filtering = false
 74→		case keyBackspace:
 75→			if len(m.filter) > 0 {
 76→				m.filter = m.filter[:len(m.filter)-1]
 77→				m.applyFilter()
 78→			}
 79→		default:
 80→			if len(keyMsg.String()) == 1 {
 81→				m.filter += keyMsg.String()
 82→				m.applyFilter()
 83→			}
 84→		}
 85→		return m, nil
 86→	}
 87→
 88→	switch keyMsg.String() {
 89→	case keyJ, keyDown:
 90→		if m.showDetail {
 91→			m.scrollPos++
 92→		} else if m.cursor < len(m.filtered)-1 {
 93→			m.cursor++
 94→		}
 95→	case keyK, keyUp:
 96→		if m.showDetail {
 97→			if m.scrollPos > 0 {
 98→				m.scrollPos--
 99→			}
100→		} else if m.cursor > 0 {
101→			m.cursor--
102→		}
103→	case keyEnter:
104→		if len(m.filtered) > 0 {
105→			m.showDetail = !m.showDetail
106→			m.scrollPos = 0
107→		}
108→	case keyEsc:
109→		if m.showDetail {
110→			m.showDetail = false
111→			m.scrollPos = 0
112→		} else if m.filter != "" {
113→			m.filter = ""
114→			m.applyFilter()
115→		}
116→	case keyFilter:
117→		m.filtering = true
118→	}
119→
120→	return m, nil
121→}
122→
123→func (m sessionsModel) view(width, height int) string {
124→	if m.err != nil {
125→		return errorStyle.Render(fmt.Sprintf("Error loading sessions: %v", m.err))
126→	}
127→
128→	if m.showDetail && m.cursor < len(m.filtered) {
129→		return m.renderDetail(width, height)
130→	}
131→
132→	return m.renderList(width, height)
133→}
134→
135→func (m sessionsModel) renderList(_ int, height int) string {
136→	var lines []string
137→
138→	// Header
139→	headerText := fmt.Sprintf("Sessions (%d)", len(m.filtered))
140→	if m.filter != "" {
141→		headerText += "  filter: " + m.filter
142→	}
143→	if m.filtering {
144→		headerText += dimStyle.Render("  type to filter, Enter to confirm, Esc to cancel")
145→	}
146→	lines = append(lines, "  "+titleStyle.Render(headerText))
147→	lines = append(lines, "")
148→
149→	if len(m.filtered) == 0 {
150→		lines = append(lines, "  "+dimStyle.Render("No sessions found"))
151→		return strings.Join(lines, "\n")
152→	}
153→
154→	for i, s := range m.filtered {
155→		shortID := s.ID
156→		if len(shortID) > 12 {
157→			shortID = shortID[:12]
158→		}
159→
160→		desc := s.Description
161→		if desc == "" || desc == strategy.NoDescription {
162→			desc = dimStyle.Render("(no description)")
163→		} else {
164→			desc = truncate(desc, 50)
165→		}
166→
167→		age := timeAgo(s.StartTime)
168→		cpCount := len(s.Checkpoints)
169→		stratName := s.Strategy
170→		if stratName == "" {
171→			stratName = "-"
172→		}
173→
174→		line := fmt.Sprintf("  %-12s  %s  %s  %s  %d cp",
175→			shortID, desc, dimStyle.Render(stratName), dimStyle.Render(age), cpCount)
176→
177→		if i == m.cursor {
178→			line = selectedItemStyle.Render(line)
179→		}
180→
181→		lines = append(lines, line)
182→	}
183→
184→	// Scroll if needed
185→	visibleStart := 0
186→	headerLines := 2
187→	maxVisible := height - headerLines
188→	if maxVisible < 1 {
189→		maxVisible = 1
190→	}
191→
192→	if m.cursor-visibleStart >= maxVisible {
193→		visibleStart = m.cursor - maxVisible + 1
194→	}
195→
196→	result := lines[:headerLines] // always show header
197→	dataLines := lines[headerLines:]
198→	end := visibleStart + maxVisible
199→	if end > len(dataLines) {
200→		end = len(dataLines)
201→	}
202→	if visibleStart < len(dataLines) {
203→		result = append(result, dataLines[visibleStart:end]...)
204→	}
205→
206→	return strings.Join(result, "\n")
207→}
208→
209→func (m sessionsModel) renderDetail(_ int, height int) string {
210→	s := m.filtered[m.cursor]
211→
212→	var lines []string
213→	lines = append(lines, titleStyle.Render("Session Detail"))
214→	lines = append(lines, "")
215→	lines = append(lines, fmt.Sprintf("  %s  %s", labelStyle.Render("ID:"), valueStyle.Render(s.ID)))
216→	lines = append(lines, fmt.Sprintf("  %s  %s", labelStyle.Render("Description:"), valueStyle.Render(s.Description)))
217→	lines = append(lines, fmt.Sprintf("  %s  %s", labelStyle.Render("Strategy:"), valueStyle.Render(s.Strategy)))
218→	lines = append(lines, fmt.Sprintf("  %s  %s", labelStyle.Render("Started:"), valueStyle.Render(s.StartTime.Format("2006-01-02 15:04:05"))))
219→	lines = append(lines, "")
220→
221→	lines = append(lines, fmt.Sprintf("  %s (%d)", labelStyle.Render("Checkpoints:"), len(s.Checkpoints)))
222→	lines = append(lines, "")
223→
224→	for _, cp := range s.Checkpoints {
225→		cpType := cpTypeSession
226→		if cp.IsTaskCheckpoint {
227→			cpType = cpTypeTask
228→		}
229→		cpID := cp.CheckpointID.String()
230→		if cpID == "" {
231→			cpID = "(none)"
232→		}
233→
234→		lines = append(lines, fmt.Sprintf("    %s  %s  %s  %s",
235→			dimStyle.Render(cpID),
236→			dimStyle.Render("["+cpType+"]"),
237→			cp.Message,
238→			dimStyle.Render(timeAgo(cp.Timestamp)),
239→		))
240→	}
241→
242→	lines = append(lines, "")
243→	lines = append(lines, dimStyle.Render("  Press Esc to go back"))
244→
245→	// Apply scroll
246→	start := m.scrollPos
247→	end := start + height
248→	if end > len(lines) {
249→		end = len(lines)
250→	}
251→	if start >= len(lines) {
252→		start = max(0, len(lines)-1)
253→	}
254→
255→	return strings.Join(lines[start:end], "\n")
256→}
