 62→func (m checkpointsModel) update(msg tea.Msg) (checkpointsModel, tea.Cmd) {
 63→	keyMsg, ok := msg.(tea.KeyMsg)
 64→	if !ok {
 65→		return m, nil
 66→	}
 67→
 68→	// Handle confirmation dialog
 69→	if m.confirming {
 70→		switch keyMsg.String() {
 71→		case keyY, keyYUpper:
 72→			m.confirming = false
 73→			if m.cursor < len(m.filtered) {
 74→				point := m.filtered[m.cursor]
 75→				return m, func() tea.Msg {
 76→					return rewindRequestMsg{pointID: point.ID}
 77→				}
 78→			}
 79→		case keyN, keyNUpper, keyEsc:
 80→			m.confirming = false
 81→		}
 82→		return m, nil
 83→	}
 84→
 85→	// Handle filter input
 86→	if m.filtering {
 87→		switch keyMsg.String() {
 88→		case keyEsc:
 89→			m.filtering = false
 90→			m.filter = ""
 91→			m.applyFilter()
 92→		case keyEnter:
 93→			m.filtering = false
 94→		case keyBackspace:
 95→			if len(m.filter) > 0 {
 96→				m.filter = m.filter[:len(m.filter)-1]
 97→				m.applyFilter()
 98→			}
 99→		default:
100→			if len(keyMsg.String()) == 1 {
101→				m.filter += keyMsg.String()
102→				m.applyFilter()
103→			}
104→		}
105→		return m, nil
106→	}
107→
108→	switch keyMsg.String() {
109→	case keyJ, keyDown:
110→		if m.showDetail {
111→			m.scrollPos++
112→		} else if m.cursor < len(m.filtered)-1 {
113→			m.cursor++
114→		}
115→	case keyK, keyUp:
116→		if m.showDetail {
117→			if m.scrollPos > 0 {
118→				m.scrollPos--
119→			}
120→		} else if m.cursor > 0 {
121→			m.cursor--
122→		}
123→	case keyEnter:
124→		if len(m.filtered) > 0 {
125→			m.showDetail = !m.showDetail
126→			m.scrollPos = 0
127→		}
128→	case keyEsc:
129→		if m.showDetail {
130→			m.showDetail = false
131→			m.scrollPos = 0
132→		} else if m.filter != "" {
133→			m.filter = ""
134→			m.applyFilter()
135→		}
136→	case keyFilter:
137→		m.filtering = true
138→	case keyR:
139→		if len(m.filtered) > 0 && !m.showDetail {
140→			m.confirming = true
141→		}
142→	}
143→
144→	return m, nil
145→}
