147→func (m checkpointsModel) view(width, height int) string {
148→	if m.err != nil {
149→		return errorStyle.Render(fmt.Sprintf("Error loading checkpoints: %v", m.err))
150→	}
151→
152→	if m.confirming && m.cursor < len(m.filtered) {
153→		return m.renderConfirmation(width, height)
154→	}
155→
156→	if m.showDetail && m.cursor < len(m.filtered) {
157→		return m.renderDetail(width, height)
158→	}
159→
160→	return m.renderList(width, height)
161→}
