163→func (m checkpointsModel) renderList(_ int, height int) string {
164→	var lines []string
165→
166→	// Header
167→	headerText := fmt.Sprintf("Checkpoints (%d)", len(m.filtered))
168→	if m.filter != "" {
169→		headerText += "  filter: " + m.filter
170→	}
171→	if m.filtering {
172→		headerText += dimStyle.Render("  type to filter, Enter to confirm, Esc to cancel")
173→	}
174→	lines = append(lines, "  "+titleStyle.Render(headerText))
175→	lines = append(lines, "")
176→
177→	if len(m.filtered) == 0 {
178→		lines = append(lines, "  "+dimStyle.Render("No checkpoints found"))
179→		return strings.Join(lines, "\n")
180→	}
181→
182→	for i, p := range m.filtered {
183→		cpType := cpTypeSession
184→		if p.IsTaskCheckpoint {
185→			cpType = cpTypeTask
186→		}
187→		if p.IsLogsOnly {
188→			cpType = cpTypeCommitted
189→		}
190→
191→		cpID := p.CheckpointID.String()
192→		if cpID == "" {
193→			cpID = truncate(p.ID, 12)
194→		}
195→
196→		prompt := truncate(p.SessionPrompt, 40)
197→		if prompt == "" {
198→			prompt = truncate(p.Message, 40)
199→		}
200→
201→		agentStr := string(p.Agent)
202→		if agentStr == "" {
203→			agentStr = "-"
204→		}
205→
206→		line := fmt.Sprintf("  %-12s  %-10s  %-14s  %-10s  %s",
207→			cpID,
208→			dimStyle.Render("["+cpType+"]"),
209→			agentStr,
210→			dimStyle.Render(timeAgo(p.Date)),
211→			prompt,
212→		)
213→
214→		if i == m.cursor {
215→			line = selectedItemStyle.Render(line)
216→		}
217→
218→		lines = append(lines, line)
219→	}
220→
221→	// Scroll
222→	visibleStart := 0
223→	headerLines := 2
224→	maxVisible := height - headerLines
225→	if maxVisible < 1 {
226→		maxVisible = 1
227→	}
228→
229→	if m.cursor-visibleStart >= maxVisible {
230→		visibleStart = m.cursor - maxVisible + 1
231→	}
232→
233→	result := lines[:headerLines]
234→	dataLines := lines[headerLines:]
235→	end := visibleStart + maxVisible
236→	if end > len(dataLines) {
237→		end = len(dataLines)
238→	}
239→	if visibleStart < len(dataLines) {
240→		result = append(result, dataLines[visibleStart:end]...)
241→	}
242→
243→	return strings.Join(result, "\n")
244→}
