 32→func (m *activeModel) setSessions(states []*session.State) {
 33→	// Filter to active sessions only (no EndedAt)
 34→	var active []*session.State
 35→	for _, s := range states {
 36→		if s.EndedAt == nil {
 37→			active = append(active, s)
 38→		}
 39→	}
 40→	m.states = active
