 43→func (m activeModel) update(msg tea.Msg) (activeModel, tea.Cmd) { //nolint:unparam // tea.Cmd needed for consistent tab interface
 44→	if keyMsg, ok := msg.(tea.KeyMsg); ok {
 45→		switch keyMsg.String() {
 46→		case keyJ, keyDown:
 47→			if m.showDetail {
 48→				m.scrollPos++
 49→			} else if m.cursor < len(m.states)-1 {
 50→				m.cursor++
 51→			}
 52→		case keyK, keyUp:
 53→			if m.showDetail {
 54→				if m.scrollPos > 0 {
 55→					m.scrollPos--
 56→				}
 57→			} else if m.cursor > 0 {
 58→				m.cursor--
 59→			}
 60→		case keyEnter:
 61→			if len(m.states) > 0 {
 62→				m.showDetail = !m.showDetail
 63→				m.scrollPos = 0
 64→			}
 65→		case keyEsc:
 66→			m.showDetail = false
 67→			m.scrollPos = 0
 68→		}
 69→	}
 70→	return m, nil
 71→}
